UNIX = """git clone https://github.com/karemdm/ppe-compliance-vlm.git
cd ppe-compliance-vlm
python3 -m venv .venv
source .venv/bin/activate
pip install -r requirements.txt
pip install -e ."""
PS = UNIX.replace("python3 -m venv", "python -m venv").replace("source .venv/bin/activate", ".venv\\Scripts\\Activate.ps1")
CMD = PS.replace(".venv\\Scripts\\Activate.ps1", ".venv\\Scripts\\activate.bat")
INSTALL = {"Linux / macOS": UNIX, "Windows · PowerShell": PS, "Windows · cmd": CMD}
APP = "ppe-compliance --vlm-model HuggingFaceTB/SmolVLM-500M-Instruct"
HEADLESS = ("ppe-compliance analyze --input samples/construction_site.mp4 --output outputs/report.json "
            "--save-video outputs/construction_site.mp4 --no-vlm")

